"Урок 27. Сигналы в космос": "Дарс 27. Сигналҳо ба кайҳон",
"Сигналы в космос": "Сигналҳо ба кайҳон",
"Объяснять, что такое оратория, и рассказывать, как люди с давних пор связывали музыку и звёздное небо.": "Фаҳмонда тавонистан, ки оратория чист ва нақл кардан, ки мардум аз замонҳои қадим мусиқӣ ва осмони пурситораро чӣ тавр бо ҳам мепайвастанд.",
"Вселенная": "Коинот",
"Вселенная — это космос: звёзды, планеты и всё, что за пределами Земли. По-казахски это «ғалам», по-английски — «cosmos».": "Коинот — ин кайҳон аст: ситораҳо, сайёраҳо ва ҳар чизе, ки берун аз Замин аст. Бо забони қазоқӣ он «ғалам», бо забони англисӣ — «cosmos» аст.",
"Звёзды и степь": "Ситораҳо ва дашт",
"Наши предки смотрели на звёздное небо и наблюдали за небесными светилами. Звёзды помогали им ориентироваться в сторонах света и находить дорогу в степи.": "Аҷдодони мо ба осмони пурситора нигоҳ мекарданд ва ба ҷирмҳои осмонӣ назорат мебурданд. Ситораҳо ба онҳо дар муайян кардани самтҳои ҷаҳон ва ёфтани роҳ дар дашт кумак мекарданд.",
"Акыны и звёзды": "Ақинҳо ва ситораҳо",
"Акыны хорошо знали основные планеты. Они воспевали их в своих песнях и складывали о них легенды.": "Ақинҳо сайёраҳои асосиро хуб медонистанд. Онҳо дар сурудҳояшон ин сайёраҳоро васф мекарданд ва дар бораашон афсонаҳо месохтанд.",
"Есепши": "Есепшиҳо",
"Есепши — это «счётчики»: люди, которые много лет вели наблюдения. Они давали прогнозы погоды и определяли время сезонных работ и перекочёвки на жайлау.": "Есепшиҳо — ин «ҳисобкунандагон» мебошанд: одамоне, ки солҳои зиёд мушоҳида мебурданд. Онҳо пешгӯии обу ҳаво мекарданд ва вақти корҳои мавсимӣ ва кӯчидан ба яйлоқро муайян менамуданд.",
"Оратория и композитор": "Оратория ва оҳангсоз",
"Оратория — большое музыкальное произведение. Сыдык Мухамеджанов — казахский композитор (1924–1991), автор оратории «Голос веков», в которую он ввёл известную народную песню.": "Оратория — асари бузурги мусиқӣ аст. Сидиқ Муҳамеҷонов — оҳангсози қазоқ (1924–1991), муаллифи ораторияи «Садои асрҳо», ки ӯ суруди машҳури халқиро ба он ворид кардааст.",
"Два созвездия — разные названия": "Ду ситорагурӯҳ — номҳои гуногун",
"Созвездия Большая и Малая Медведица в разные эпохи носили разные названия. Разложи названия по созвездиям.": "Ситорагурӯҳҳои Хирси Калон ва Хирси Хурд дар даврони гуногун номҳои гуногун доштанд. Номҳоро аз рӯи ситорагурӯҳҳо ҷудо кун.",
