"Космическая музыка": "Мусиқии кайҳонӣ",
"Объяснять, какую музыку называют космической, и называть инструменты и музыкантов, связанных с ней.": "Фаҳмонда тавонистан, ки кадом мусиқиро кайҳонӣ меноманд ва номбар кардани асбобҳо ва мусиқинавозоне, ки бо он алоқаманданд.",
"Космические звуки": "Садоҳои кайҳонӣ",
"С момента покорения космоса человек стал придумывать новые инструменты, которые издают «космические звуки». Так появился термин «космическая музыка».": "Аз замони тасхири кайҳон инсон ба ихтироъ кардани асбобҳои нав шурӯъ кард, ки «садоҳои кайҳонӣ» мебароранд. Ҳамин тавр истилоҳи «мусиқии кайҳонӣ» пайдо шуд.",
"По-казахски она называется «ғарыш музыкасы», по-английски — space music. Создать её можно с помощью электромузыкальных инструментов.": "Бо забони қазоқӣ он «ғарыш музыкасы», бо забони англисӣ — space music ном дорад. Онро бо ёрии асбобҳои электромусиқӣ сохтан мумкин аст.",
"Синтезатор": "Синтезатор",
"Синтезатор — самый распространённый электромузыкальный инструмент. С его помощью создают «космическую» музыку.": "Синтезатор — паҳнтарин асбоби электромусиқӣ аст. Бо ёрии он мусиқии «кайҳонӣ» месозанд.",
"Жан-Мишель Жарр": "Жан-Мишел Жарр",
"Это французский композитор, который играет в основном на синтезаторах. Он одним из первых стал использовать синтезатор для «космических» композиций.": "Ин оҳангсози фаронсавӣ аст, ки асосан бо синтезаторҳо менавозад. Ӯ яке аз аввалинҳо шуд, ки синтезаторро барои композитсияҳои «кайҳонӣ» истифода бурд.",
"Глюкофон": "Глюкофон",
"В 2005 году мир впервые услышал космическую музыку глюкофона. Доминиканский музыкант Фелле Вега показал первый прототип под названием «Tambiro».": "Дар соли 2005 ҷаҳон бори аввал мусиқии кайҳонии глюкофонро шунид. Мусиқинавози доминиканӣ Фелле Вега нахустин прототипро бо номи «Tambiro» нишон дод.",
