"Композиторы разных стран использовали в своих произведениях тему космоса. Музыка помогает почувствовать красоту и величие космического пространства.": "Оҳангсозони кишварҳои гуногун дар асарҳои худ мавзӯи кайҳонро истифода кардаанд. Мусиқӣ ба ҳис кардани зебоӣ ва бузургии фазои кайҳонӣ кумак мекунад.",
"Энергия звука": "Энергияи садо",
"Так называется грандиозная постановка в мире классической музыки. Шоу прошло в 2017 году в Астане и стало событием мирового уровня.": "Ин номи намоиши азим дар олами мусиқии классикӣ мебошад. Намоиш соли 2017 дар Остона баргузор шуд ва ба рӯйдоди сатҳи ҷаҳонӣ табдил ёфт.",
"Идея проекта": "Ғояи лоиҳа",
"Задумал шоу известный казахстанский скрипач и дирижёр Марат Бисенгалиев. Он был солистом и дирижёром проекта.": "Намоишро скрипканавоз ва дирижёри машҳури қазоқистонӣ Марат Бисенгалиев тарҳрезӣ кардааст. Ӯ яккахон ва дирижёри лоиҳа буд.",
"Музыка и технологии": "Мусиқӣ ва технологияҳо",
"Создатели объединили классическую музыку в исполнении симфонического оркестра с передовыми технологиями. В шоу использовали новые 3D звуковые технологии.": "Созандагон мусиқии классикиро бо иҷрои оркестри симфонӣ бо технологияҳои пешрафта муттаҳид карданд. Дар намоиш технологияҳои нави садои 3D истифода шуданд.",
"Команда проекта": "Гурӯҳи лоиҳа",
"Музыку написал британский композитор Карл Дженкинс. Режиссёр-постановщик — Василий Бархатов. Над шоу работала международная команда режиссёров, артистов, звукорежиссёров и продюсеров.": "Мусиқиро оҳангсози бритониёӣ Карл Дженкинс навиштааст. Коргардони саҳнагузор — Василий Бархатов. Болои намоиш гурӯҳи байналмилалии коргардонҳо, ҳунармандон, мутахассисони садо ва продюсерҳо кор мекард.",
"Кто есть кто в проекте": "Кӣ дар лоиҳа кӣ аст",
"Определи, о ком говорит карточка. Барсик подсказывает: вспомни, кто что делал в проекте «Энергия звука».": "Муайян кун, ки корт дар бораи кӣ нақл мекунад. Барсик маслиҳат медиҳад: ба хотир ор, ки дар лоиҳаи «Энергияи садо» кӣ чӣ кор кардааст.",
"О каком участнике проекта идёт речь?": "Сухан дар бораи кадом иштирокчии лоиҳа меравад?",
