"Урок 30. Вселенная звука": "Дарс 30. Коиноти садо",
"Вселенная звука": "Коиноти садо",
"Объяснять, почему музыку называют вселенной звука, и называть, как создаются новые музыкальные инструменты и произведения.": "Тавзеҳ додан, ки чаро мусиқиро коиноти садо меноманд, ва номбар кардани роҳҳои эҷоди асбобҳо ва асарҳои нави мусиқӣ.",
"Музыку можно назвать вселенной. Это не огромное космическое пространство, а безграничное пространство, заполненное всевозможными звуками.": "Мусиқиро метавон коинот номид. Ин фазои азими кайҳонӣ нест, балки фазои беканоре аст, ки бо садоҳои гуногун пур шудааст.",
"Какая Вселенная в космосе": "Коинот дар кайҳон чӣ гуна аст",
"Современная наука пока не знает, каковы реальные размеры Вселенной и есть ли у неё границы.": "Илми имрӯза ҳоло намедонад, ки андозаҳои воқеии Коинот чӣ қадаранд ва оё он марз дорад.",
"Песня «Этот большой мир»": "Суруди «Ин ҷаҳони бузург»",
"Её музыку написал В. Чернышев, а слова — Р. Рождественский. Песню слышно в кинофильме «Москва-Кассиопея».": "Мусиқии онро В. Чернишев навиштааст ва матнро Р. Рождественский. Суруд дар кинофильми «Маскав-Кассиопея» шунида мешавад.",
"Звуки Земли в космосе": "Садоҳои Замин дар кайҳон",
"В песне космонавтам советуют взять в полёт звуки природы и обычной земной жизни. Так напоминание о доме летит вместе с ними.": "Дар суруд ба кайҳоннавардон маслиҳат медиҳанд, ки садоҳои табиат ва зиндагии оддии заминиро ба парвоз бо худ баранд. Ҳамин тавр ёдоварӣ аз хона бо онҳо парвоз мекунад.",
"Вселенная звука расширяется": "Коиноти садо васеъ мешавад",
"Создаются новые произведения и инструменты, появляются переложения и аранжировки, восстанавливаются утерянные инструменты. Мы слушаем музыку и наслаждаемся музыкой природы.": "Асарҳо ва асбобҳои нав эҷод мешаванд, гузоришҳо ва аранжировкаҳо пайдо мешаванд, асбобҳои гумшуда барқарор карда мешаванд. Мо мусиқиро гӯш мекунем ва аз мусиқии табиат лаззат мебарем.",
"Разложи по творческим группам": "Ба гурӯҳҳои эҷодӣ тақсим кун",
"Четыре творческие группы готовят проект «Вселенная звука». Определи, к какой группе относится каждая карточка.": "Чор гурӯҳи эҷодӣ лоиҳаи «Коиноти садо»-ро тайёр мекунанд. Муайян кун, ки ҳар корт ба кадом гурӯҳ тааллуқ дорад.",
"К какой творческой группе относится?": "Ба кадом гурӯҳи эҷодӣ тааллуқ дорад?",
