"Пословица таджикского народа советует забыть прошлое.": "Зарбулмасали халқи тоҷик маслиҳат медиҳад, ки гузаштаро фаромӯш кунем.",
"Секреты записи музыкальных файлов изучают на уроках физкультуры.": "Сирри сабти файлҳои мусиқиро дар дарсҳои тарбияи ҷисмонӣ меомӯзанд.",
"Да, такое направление появилось, потому что компьютеры вошли в нашу жизнь.": "Бале, чунин самт аз он сабаб пайдо шуд, ки компютерҳо ба зиндагии мо ворид шуданд.",
"Музыку сочиняет человек, а компьютер помогает.": "Мусиқиро инсон эҷод мекунад, ва компютер кумак мекунад.",
"Именно так: записать и обработать.": "Маҳз ҳамин тавр: сабт ва коркард кардан.",
"SunVox, NanoStudio и DarkWaveStudio — такие программы.": "SunVox, NanoStudio ва DarkWaveStudio — чунин барномаҳо мебошанд.",
"Это Адиль Ордаев.": "Ин Адил Ордаев аст.",
"В видеофрагменте роботы исполняют этот танец.": "Дар видеопора роботҳо ин рақсро иҷро мекунанд.",
"Это композитор Л. Мельникова.": "Ин оҳангсоз Л. Мельникова аст.",
"В ней есть приветствия на разных языках мира.": "Дар он салому алейкҳо ба забонҳои гуногуни ҷаҳон ҳастанд.",
"Она советует беречь прошлое, но знать и новое.": "Он маслиҳат медиҳад, ки гузаштаро ҳифз кунем, вале навро низ донем.",
"О них узнают на уроках информатики.": "Дар бораи онҳо дар дарсҳои информатика мефаҳманд.",
"Верно. Да, такое направление появилось, потому что компьютеры вошли в нашу жизнь.": "Дуруст. Бале, чунин самт аз он сабаб пайдо шуд, ки компютерҳо ба зиндагии мо ворид шуданд.",
"Неверно. Музыку сочиняет человек, а компьютер помогает.": "Нодуруст. Мусиқиро инсон эҷод мекунад, ва компютер кумак мекунад.",
"Верно. Именно так: записать и обработать.": "Дуруст. Маҳз ҳамин тавр: сабт ва коркард кардан.",
"Верно. SunVox, NanoStudio и DarkWaveStudio — такие программы.": "Дуруст. SunVox, NanoStudio ва DarkWaveStudio — чунин барномаҳо мебошанд.",
"Верно. Это Адиль Ордаев.": "Дуруст. Ин Адил Ордаев аст.",
"Верно. В видеофрагменте роботы исполняют этот танец.": "Дуруст. Дар видеопора роботҳо ин рақсро иҷро мекунанд.",
"Верно. Это композитор Л. Мельникова.": "Дуруст. Ин оҳангсоз Л. Мельникова аст.",
"Неверно. В ней есть приветствия на разных языках мира.": "Нодуруст. Дар он салому алейкҳо ба забонҳои гуногуни ҷаҳон ҳастанд.",
"Неверно. Она советует беречь прошлое, но знать и новое.": "Нодуруст. Он маслиҳат медиҳад, ки гузаштаро ҳифз кунем, вале навро низ донем.",
"Неверно. О них узнают на уроках информатики.": "Нодуруст. Дар бораи онҳо дар дарсҳои информатика мефаҳманд.",
"Найди: Человек": "Ёбед: Инсон",
"Найди: Компьютер помогает": "Ёбед: Компютер кумак мекунад",
"Найди: Компьютерная музыка": "Ёбед: Мусиқии компютерӣ",
