"Урок 32. Без прошлого нет будущего": "Дарс 32. Бе гузашта оянда нест",
"Без прошлого нет будущего": "Бе гузашта оянда нест",
"Объяснять, что такое музыка Победы, и подбирать к песне фото- и видеофрагменты, которые поддерживают её содержание.": "Тавзеҳ додан, ки мусиқии Ғалаба чист, ва ба суруд фотоҳо ва видеопораҳое интихоб кардан, ки мазмуни онро дастгирӣ мекунанд.",
"Праздничный май": "Моҳи майи ҷашнӣ",
"В каждом празднике есть свои особенности и традиции. Май особенный: в нём сразу несколько праздников, и у каждого есть песни-символы.": "Дар ҳар ид хусусиятҳо ва расму оини худ ҳаст. Май махсус аст: дар он якбора якчанд ид ҳаст ва ҳар кадом сурудҳои рамзии худро дорад.",
"Музыка Победы": "Мусиқии Ғалаба",
"Так называют музыку, посвящённую Дню Победы. По-казахски она называется «Жеңіс музыкасы», по-английски — music of Victory.": "Ин мусиқиеро меноманд, ки ба Рӯзи Ғалаба бахшида шудааст. Ба қазоқӣ он «Женис музыкасы», ба забони англисӣ — music of Victory ном дорад.",
"Песня «День Победы»": "Суруди «Рӯзи Ғалаба»",
"Слова и музыку этой песни написала Л. Мельникова. В ней рассказывается о празднике мира, о памяти и о мирном Казахстане.": "Матн ва мусиқии ин сурудро Л. Мельникова навиштааст. Дар он дар бораи иди сулҳ, хотира ва Қазоқистони осоишта нақл мешавад.",
"Два языка в песне": "Ду забон дар суруд",
"Припев этой песни звучит на русском и на казахском языках. Так песня объединяет людей, которые говорят на разных языках.": "Такрори ин суруд ба забонҳои русӣ ва қазоқӣ садо медиҳад. Ҳамин тавр суруд одамонеро, ки ба забонҳои гуногун сухан мегӯянд, муттаҳид мекунад.",
"Видеоряд к музыке": "Силсилаи тасвирӣ ба мусиқӣ",
"Фото- и видеофрагменты нужно подбирать так, чтобы они поддерживали содержание песни. Простой набор кадров о празднике — это ещё не видеоклип.": "Фотоҳо ва видеопораҳоро бояд чунон интихоб кард, ки мазмуни сурудро дастгирӣ кунанд. Маҷмӯи оддии кадрҳо дар бораи ид ҳоло видеоклип нест.",
"Разложи по праздникам мая": "Ба идҳои моҳи май тақсим кун",
"Определи, к какому майскому празднику относится каждая карточка.": "Муайян кун, ки ҳар корт ба кадом иди моҳи май тааллуқ дорад.",
"К какому празднику относится?": "Ба кадом ид тааллуқ дорад?",
