"Праздник единства народов связан с дружбой народов.": "Иди ваҳдати халқҳо бо дӯстии халқҳо алоқаманд аст.",
"Песню «День Победы» поют только на английском языке.": "Суруди «Рӯзи Ғалаба»-ро танҳо ба забони англисӣ мехонанд.",
