"Там духовой оркестр.": "Дар он ҷо оркестри бодӣ ҳаст.",
"На русском и на казахском.": "Ба русӣ ва ба қазоқӣ.",
"Жеңіс — победа.": "Женис — ғалаба.",
"Он символизирует конец учебного года.": "Он поёни соли хониро рамзгузорӣ мекунад.",
"Марш — бодрая музыка для строя.": "Марш — мусиқии боҷасорат барои сафф аст.",
"Это главная тема праздника.": "Ин мавзӯи асосии ид аст.",
"Припев русский и казахский.": "Такрор русӣ ва қазоқӣ аст.",
"Верно. В мае несколько праздников.": "Дуруст. Дар моҳи май якчанд ид ҳаст.",
"Верно. Она автор слов и музыки.": "Дуруст. Ӯ муаллифи матн ва мусиқӣ аст.",
"Неверно. Там духовой оркестр.": "Нодуруст. Дар он ҷо оркестри бодӣ ҳаст.",
"Верно. На русском и на казахском.": "Дуруст. Ба русӣ ва ба қазоқӣ.",
"Верно. Жеңіс — победа.": "Дуруст. Женис — ғалаба.",
"Неверно. Видеоряд должен поддерживать содержание песни.": "Нодуруст. Силсилаи тасвирӣ бояд мазмуни сурудро дастгирӣ кунад.",
"Верно. Он символизирует конец учебного года.": "Дуруст. Он поёни соли хониро рамзгузорӣ мекунад.",
"Неверно. Марш — бодрая музыка для строя.": "Нодуруст. Марш — мусиқии боҷасорат барои сафф аст.",
"Верно. Это главная тема праздника.": "Дуруст. Ин мавзӯи асосии ид аст.",
