"Урок 33. Прекрасное далёко": "Дарс 33. Дурии зебо",
"Прекрасное далёко": "Дурии зебо",
"Объяснять, что такое авторская песня, и называть известных бардов и песни урока.": "Шарҳ додани он, ки суруди муаллифӣ чист, ва номбар кардани бардҳои машҳур ва сурудҳои дарс.",
"Будущее": "Оянда",
"Будущее по-казахски «болашақ», по-английски «future». Во время прогулки или похода хорошо мечтать о том, каким оно будет.": "Оянда ба қазоқӣ «болашақ», ба англисӣ «future» аст. Ҳангоми сайру гашт ё сафар орзу кардан хуб аст, ки он чӣ гуна мешавад.",
"Это песня Е. Крылатова из кинофильма «Гостья из будущего». Она заставляет подумать, что нужно делать сегодня, чтобы будущее было прекрасным для всех.": "Ин суруди Е. Крылатов аз филми «Меҳмон аз оянда» аст. Он ба фикр водор мекунад, ки имрӯз чӣ кор кардан лозим аст, то ояндаи ҳама зебо бошад.",
"Авторская песня": "Суруди муаллифӣ",
"Авторскую песню ещё называют бардовской. Её особенность: слова, музыку, аккомпанемент и исполнение создаёт один и тот же человек.": "Суруди муаллифиро боз бардӣ низ меноманд. Хусусияти он: суханон, оҳанг, ҳамроҳӣ ва иҷрои онро як нафар месозад.",
"Известные барды": "Бардҳои машҳур",
"Авторские песни писали и исполняли Булат Окуджава, Юрий Визбор, Владимир Высоцкий, Ада Якушева, Татьяна и Сергей Никитины, Виктор Берковский, Дмитрий Сухарев.": "Сурудҳои муаллифиро Булат Окуджава, Юрий Визбор, Владимир Высоцкий, Ада Якушева, Татьяна ва Сергей Никитинҳо, Виктор Берковский, Дмитрий Сухарев навишта ва иҷро мекарданд.",
"Почему такие песни популярны": "Чаро чунин сурудҳо маъруфанд",
"В них часто звучит тема любви к родному краю. Мелодии простые, легко запоминаются, и подпеть исполнителю может каждый. Ещё в уроке есть песня В. Шаинского «Вместе весело шагать» на слова М. Матусовского.": "Дар онҳо мавзӯи муҳаббат ба диёри зодгоҳ зуд-зуд садо медиҳад. Оҳангҳо оддӣ буда, ба осонӣ дар ёд мемонанд ва ҳар кас метавонад бо иҷрокунанда ҳамовоз шавад. Боз дар дарс суруди В. Шаинский «Якҷоя шодона қадам мезанем» бо суханони М. Матусовский ҳаст.",
"Разложи по ролям": "Аз рӯи нақшҳо ҷудо кун",
"Определи, кто перед тобой: бард или композитор и поэт, которые упомянуты в уроке.": "Муайян кун, ки дар назди ту кист: бард ё оҳангсоз ва шоире, ки дар дарс ёд шудаанд.",
"Кто это?": "Ин кист?",
