"Слова написал М. Матусовский.": "Суханонро М. Матусовский навиштааст.",
"О какой песне Г. Гладков рассказывал, как её написал?": "Г. Гладков дар бораи навиштани кадом суруд нақл кардааст?",
"«Прекрасное далёко»": "«Дурии зебо»",
"Г. Гладков написал песню «Пой, Вася!».": "Г. Гладков сурудро «Бихон, Вася!» навиштааст.",
