"Е. Крылатов назван автором песни «Прекрасное далёко», а не бардом из списка.": "Е. Крылатов ҳамчун муаллифи суруди «Дурии зебо» номбар шудааст, на ҳамчун барди рӯйхат.",
"Подпеть исполнителю могут все желающие.": "Ҳамаи хоҳишмандон метавонанд бо иҷрокунанда ҳамовоз шаванд.",
"Музыку написал В. Шаинский.": "Мусиқиро В. Шаинский навиштааст.",
"Да, он автор слов.": "Бале, ӯ муаллифи суханон аст.",
"Эта тема звучит в них часто.": "Ин мавзӯъ дар онҳо зуд садо медиҳад.",
"Верно. Верно, «болашақ» значит «будущее».": "Дуруст. Дуруст, «болашақ» маънои «оянда»-ро дорад.",
"Верно. Да, это песня Е. Крылатова из этого фильма.": "Дуруст. Бале, ин суруди Е. Крылатов аз ҳамин филм аст.",
"Неверно. В авторской песне и слова, и музыка принадлежат одному человеку.": "Нодуруст. Дар суруди муаллифӣ ҳам суханон, ҳам оҳанг ба як нафар тааллуқ дорад.",
"Верно. Эти названия обозначают один жанр.": "Дуруст. Ин номҳо як жанрро ифода мекунанд.",
"Верно. Они названы среди авторов бардовских песен.": "Дуруст. Онҳо дар байни муаллифони сурудҳои бардӣ номбар шудаанд.",
"Неверно. Е. Крылатов назван автором песни «Прекрасное далёко», а не бардом из списка.": "Нодуруст. Е. Крылатов ҳамчун муаллифи суруди «Дурии зебо» номбар шудааст, на ҳамчун барди рӯйхат.",
"Верно. Подпеть исполнителю могут все желающие.": "Дуруст. Ҳамаи хоҳишмандон метавонанд бо иҷрокунанда ҳамовоз шаванд.",
"Неверно. Музыку написал В. Шаинский.": "Нодуруст. Оҳангро В. Шаинский навиштааст.",
"Верно. Да, он автор слов.": "Дуруст. Бале, ӯ муаллифи суханон аст.",
"Неверно. Эта тема звучит в них часто.": "Нодуруст. Ин мавзӯъ дар онҳо зуд садо медиҳад.",
"Найди: Бард (авторская песня)": "Ёбед: Бард (суруди муаллифӣ)",
"Найди: Композитор или автор слов песни урока": "Ёбед: Оҳангсоз ё муаллифи суханони суруди дарс",
"Найди: Авторская песня": "Ёбед: Суруди муаллифӣ",
"Найди: Песня «Вместе весело шагать»": "Ёбед: Суруди «Якҷоя шодона қадам мезанем»",
"Урок 34. До свиданья, начальная школа! Здравствуй, будущий мой класс!": "Дарс 34. Хайр, мактаби ибтидоӣ! Салом, синфи ояндаи ман!",
"До свиданья, начальная школа! Здравствуй, будущий мой класс!": "Хайр, мактаби ибтидоӣ! Салом, синфи ояндаи ман!",
"Вспоминать музыкальные термины и понятия года и планировать музыкальные каникулы с помощью таблицы «Музыкальный ЗУХ».": "Истилоҳ ва мафҳумҳои мусиқии солро ба ёд овардан ва таътили мусиқиро бо ёрии ҷадвали «МҲМ-и мусиқӣ» банақшагирӣ кардан.",
"Что мы узнали за год": "Дар як сол чӣ ёд гирифтем",
"Ты познакомился с новыми музыкальными инструментами и узнал много терминов. Ты научился различать жанры народной песни и узнал имена великих композиторов.": "Ту бо асбобҳои нави мусиқӣ шинос шудӣ ва истилоҳҳои бисёр омӯхтӣ. Ту ҷанрҳои суруди халқиро фарқ карданро ёд гирифтӣ ва номи оҳангсозони бузургро омӯхтӣ.",
"Виды вокала": "Намудҳои овозхонӣ",
"Мы узнали три вида пения: классический вокал, современный (эстрадный) вокал и народный вокал.": "Мо се намуди сароиданро омӯхтем: овозхонии классикӣ, овозхонии муосир (эстрадӣ) ва овозхонии халқӣ.",
"Казахское народное творчество": "Эҷодиёти халқии қазоқ",
"В этом году встретились слова сал и сері, терме, термеші, жыр и жыршы. Это части богатой народной музыкальной культуры.": "Имсол калимаҳои сал ва сери, терме, термеши, жыр ва жыршы вомехӯрданд. Инҳо қисмҳои фарҳанги бойи мусиқии халқӣ мебошанд.",
"Другие важные слова": "Дигар калимаҳои муҳим",
"Макам, вариации, канон, варган, программная музыка, романс, переложение, многоголосие, культурное наследие, вселенная, космическая и компьютерная музыка, авторская песня, синтезатор.": "Макам, вариацияҳо, канон, варган, мусиқии барномавӣ, романс, мутобиқсозӣ, бисёровозӣ, мероси фарҳангӣ, коинот, мусиқии кайҳонӣ ва компютерӣ, суруди муаллифӣ, синтезатор.",
"Таблица «Музыкальный ЗУХ»": "Ҷадвали «МҲМ-и мусиқӣ»",
"Чтобы не упустить ничего летом, веди таблицу из трёх столбиков: «Знаю», «Удивился» и «Хочу узнать». Слова-маячки помогут рассказать о каникулах на первом уроке и задать вопросы.": "Барои он ки дар тобистон чизеро аз даст надиҳӣ, ҷадвали се сутунӣ бибар: «Медонам», «Ҳайрон шудам» ва «Мехоҳам донам». Калимаҳои роҳнамо кӯмак мекунанд, ки дар дарси аввал дар бораи таътил нақл кунӣ ва савол диҳӣ.",
"Разложи термины года": "Истилоҳҳои солро ҷудо кун",
