"К какой группе относится термин?": "Истилоҳ ба кадом гурӯҳ тааллуқ дорад?",
"Формы и жанры музыки": "Шаклҳо ва жанрҳои мусиқӣ",
"классический вокал": "овозхонии классикӣ",
"Это один из видов пения.": "Ин яке аз намудҳои сароидан аст.",
