"Это тоже вид пения.": "Ин низ як намуди сароидан аст.",
"народный вокал": "овозхонии халқӣ",
"Это пение в народной манере.": "Ин сароидан ба тарзи халқӣ аст.",
"сал и сері": "сал ва сери",
"Это слова из мира казахской народной культуры.": "Ин калимаҳо аз ҷаҳони фарҳанги халқии қазоқанд.",
"терме": "терме",
"Это казахское народное искусство.": "Ин санъати халқии қазоқ аст.",
"жыр и жыршы": "жыр ва жыршы",
