"Реши, в какой столбик таблицы «Музыкальный ЗУХ» нужно записать каждую запись.": "Қарор кун, ки ҳар сабтро дар кадом сутуни ҷадвали «МҲМ-и мусиқӣ» навиштан лозим аст.",
