"Народный вокал и классический вокал — это одно и то же.": "Овозхонии халқӣ ва овозхонии классикӣ як чиз аст.",
"Современный вокал называют эстрадным.": "Овозхонии муосирро эстрадӣ меноманд.",
"Канон и вариации — названия музыкальных инструментов.": "Канон ва вариацияҳо — номи асбобҳои мусиқӣ мебошанд.",
"Синтезатор — один из терминов, которые ты узнал за год.": "Синтезатор — яке аз истилоҳҳоест, ки дар як сол омӯхтӣ.",
"Песня «Прощание с начальной школой» — о космосе.": "Суруди «Видоъ бо мактаби ибтидоӣ» дар бораи кайҳон аст.",
"Жазғы демалыс — это то же, что summer vacation.": "Жазғы демалыс ҳамон summer vacation аст.",
"Урок как раз об этом.": "Дарс маҳз дар ҳамин бора аст.",
"Его можно заполнять всё лето.": "Онро тамоми тобистон пур кардан мумкин.",
"Ещё названия произведений и термины.": "Боз номи асарҳо ва истилоҳҳо.",
"И задать вопросы учителю и друзьям.": "Ва ба муаллим ва дӯстон савол додан.",
"Это разные виды вокала.": "Инҳо намудҳои гуногуни овозхонӣ мебошанд.",
"Это два названия одного вида.": "Ин ду номи як намуд аст.",
"Это формы музыки, а не инструменты.": "Ин шаклҳои мусиқӣ мебошанд, на асбобҳо.",
"Он есть в списке терминов.": "Он дар рӯйхати истилоҳҳо ҳаст.",
"Она о прощании с начальным классом.": "Он дар бораи видоъ бо синфи ибтидоӣ аст.",
