"27-сабақ. Байқоңыр": "Дарс 27. Байқонур",
"Байқоңыр": "Байқонур",
"Байқоңыр туралы музыкалық шығарманы тыңдап, оның авторларын, орындаушыларын және музыкалық формасын атау.": "Гӯш кардани асари мусиқӣ дар бораи Байқонур ва номбар кардани муаллифон, иҷрокунандагон ва шакли мусиқии он.",
"Байқоңыр қандай жер?": "Байқонур чӣ гуна ҷой аст?",
"Байқоңыр — ғарышқа зымыран ұшырылатын жер. Ғалымдар оны ғарышқа ұшуға ең қолайлы жер деп таңдаған.": "Байқонур — ҷоест, ки аз он ба кайҳон мушак парронда мешавад. Олимон онро барои парвоз ба кайҳон ҷои беҳтарин интихоб кардаанд.",
"Неге дәл Байқоңыр?": "Чаро маҳз Байқонур?",
"Байқоңыр экваторға жақын, сондықтан мұнда Жердің тартылыс күші аз. Зымыранға ғарышқа көтерілу жеңілірек.": "Байқонур ба экватор наздик аст, бинобар ин дар ин ҷо қувваи ҷозибаи Замин кам аст. Мушак осонтар ба кайҳон боло мешавад.",
"Экватор дегеніміз не?": "Экватор чист?",
"«Экватор» латын тілінде «теңестіргіш» деген мағына береді. Жер шарының дәл ортасынан өтетін шартты сызық экватор сызығы деп аталады.": "«Экватор» ба забони лотинӣ маънои «баробаркунанда»-ро дорад. Хати шартие, ки аз миёнаи дақиқи кураи Замин мегузарад, хати экватор номида мешавад.",
"«Байқоңыр» шығармасы": "Асари «Байқонур»",
"Бұл — композитор А. Алмағанбетовтың музыкалық шығармасы. Оны халық аспаптар ансамблі орындайды.": "Ин асари мусиқии оҳангсоз А. Алмаганбетов аст. Онро ансамбли асбобҳои халқӣ иҷро мекунад.",
"Кімге арналған?": "Ба кӣ бахшида шудааст?",
"Композитор шығарманы тұңғыш қазақ ғарышкері Т. Әубәкіровке арнаған. Сонымен қатар «Байқоңыр» атты ән бар: сөзін А. Рахметов, әнін А. Алмағанбетов жазған.": "Оҳангсоз асарро ба аввалин кайҳоннавар қазоқ Т. Аубакиров бахшидааст. Ҳамчунин суруде бо номи «Байқонур» ҳаст: суханашро А. Рахметов, оҳангашро А. Алмаганбетов навиштаанд.",
"Байқоңыр туралы ұғымдарды топтастыр": "Мафҳумҳои марбут ба Байқонурро гурӯҳбандӣ кун",
"Әр карточканы дұрыс топқа қой.": "Ҳар кортро ба гурӯҳи дуруст гузор.",
"Бұл ұғым қай топқа жатады?": "Ин мафҳум ба кадом гурӯҳ тааллуқ дорад?",
