"Композитор шығарманы тұңғыш қазақ ғарышкеріне арнаған.": "Оҳангсоз асарро ба аввалин кайҳоннавар қазоқ бахшидааст.",
"«Байқоңыр» әнінің сөзін А. Алмағанбетов жазған.": "Суханони суруди «Байқонур»-ро А. Алмаганбетов навиштааст.",
