"Ғарыш әуені": "Оҳанги кайҳон",
"Ғарыш ұғымын түсіндіру, халықтық, классикалық және эстрадалық музыканы ажырату, синтезатор, фортепиано және орган аспаптарын ажырата білу.": "Шарҳ додани мафҳуми кайҳон, фарқ кардани мусиқии халқӣ, классикӣ ва эстрадӣ, шинохтани асбобҳои синтезатор, фортепиано ва органро.",
"Ғарыш дегеніміз не?": "Кайҳон чист?",
"Ғарыш – Жерді қоршаған шексіз кеңістік. Күн, Ай, Жер, жұлдыздар және басқа галамшарлар ғарыш әлемін құрайды.": "Кайҳон – фазои бепоёне, ки Заминро иҳота кардааст. Офтоб, Моҳ, Замин, ситорагон ва дигар сайёраҳо олами кайҳонро ташкил медиҳанд.",
"Дидье Маруани": "Дидье Маруани",
"Дидье Маруани – француз композиторы. Оны «синтезаторлар патшасы» деп атаған. Ол «Симфония» шығармасының музыкасын жазған.": "Дидье Маруани – оҳангсози фаронсавӣ. Ӯро «шоҳи синтезаторҳо» номидаанд. Ӯ мусиқии асари «Симфония»-ро навиштааст.",
"«Спейс» рок тобы": "Гурӯҳи рок «Спейс»",
"Дидье Маруани құрған «Спейс» рок тобы 1980 жылдары бүкіл әлемге танымал болды. «Симфония» шығармасын осы топ орындаған.": "Гурӯҳи рок «Спейс», ки Дидье Маруани таъсис додааст, дар солҳои 1980 дар тамоми ҷаҳон машҳур шуд. Асари «Симфония»-ро ҳамин гурӯҳ иҷро кардааст.",
"Музыка бағыттары": "Самтҳои мусиқӣ",
"Халықтық музыка – ұлттық ән-күй, жырлар. Классикалық музыка – симфония, опера, сюита, романс. Эстрадалық музыка – электронды аспаптармен өңделген шығармалар.": "Мусиқии халқӣ – сурудҳо, куйҳо ва достонҳои миллӣ. Мусиқии классикӣ – симфония, опера, сюита, романс. Мусиқии эстрадӣ – асарҳое, ки бо асбобҳои электронӣ коркард шудаанд.",
"Поп, рок және стиль": "Поп, рок ва услуб",
"Поп музыка – көпшілікке арналған, танымал, тыңдауға жеңіл музыка. Рок музыка – электронды аспаптармен орындалатын, нақты (ауыр) ырғақты музыка. Стиль – композитор немесе орындаушының музыкалық бейнені берудегі бағыты.": "Мусиқии поп – мусиқии барои оммаи васеъ пешбинишуда, машҳур ва барои гӯш кардан осон. Мусиқии рок – мусиқии бо асбобҳои электронӣ иҷрошаванда бо ритми аниқ (вазнин). Услуб – самти оҳангсоз ё иҷрокунанда дар ифодаи симои мусиқӣ.",
"Музыка бағытын тап": "Самти мусиқиро ёб",
"Әр карточканы тиісті музыка бағытына сал. Барсик көмектеседі!": "Ҳар кортро ба самти мусиқии дахлдораш гузор. Барсик кӯмак мекунад!",
