"Мен ғарышкер боламын": "Ман кайҳоннавард мешавам",
"Ғарыш тақырыбындағы шығармаларды атау және оркестрлік пьеса мен әнді бір-бірінен ажырату.": "Асарҳои ба мавзӯи кайҳон бахшидашударо номбар кардан ва пьесаи оркестриро аз суруд фарқ кардан.",
"Адамның Айға ұшуы": "Парвози инсон ба Моҳ",
"20-ғасырдағы үлкен жаңалықтардың бірі — адамның Айға ұшуы. Бұл оқиға әлем музыканттарына да қатты әсер етті.": "Яке аз кашфиётҳои бузурги асри 20 — парвози инсон ба Моҳ. Ин ҳодиса ба мусиқинавозони ҷаҳон низ сахт таъсир кард.",
"Ғарыш тақырыбы": "Мавзӯи кайҳон",
"Музыканттар ғарыш тақырыбына түрлі жанрда шығармалар жазды. Олардың бірі — америкалық композитор Ч. Айвздың оркестрлік пьесасы.": "Мусиқинавозон ба мавзӯи кайҳон асарҳо дар жанрҳои гуногун эҷод карданд. Яке аз онҳо пьесаи оркестрии композитори амрикоӣ Ч. Айвз аст.",
"«Ғарыш пейзажы»": "«Манзараи кайҳонӣ»",
"Бұл пьесаны симфониялық оркестр орындайды. Кейін шығарманың аты өзгеріп, «Жауапсыз қалған сұрақ» болды.": "Ин пьесаро оркестри симфонӣ иҷро мекунад. Баъдтар номи асар тағйир ёфта, «Саволи беҷавоб» шуд.",
"Музыка арқылы әңгіме": "Ҳикоя тавассути мусиқӣ",
"Музыкада төрт ғарышкер белгісіз ғаламшарға ұшады. Ондағы тұрғындар дыбыс арқылы 7 рет сұрақ қояды, бірақ жауап ала алмайды.": "Дар мусиқӣ чор кайҳоннавард ба сайёраи ношинос парвоз мекунанд. Сокинони он бо овоз 7 бор савол медиҳанд, вале ҷавоб гирифта наметавонанд.",
"«Мен ғарышкер боламын»": "«Ман кайҳоннавард мешавам»",
"Бұл — ғарышкер болуды армандайтын баланың әні. Өлеңін С. Қамшыгер, әнін Ө. Алтаев жазған. Әнде шумақтар мен қайырма бар.": "Ин суруди кӯдакест, ки орзуи кайҳоннавард шуданро дорад. Шеърашро С. Камшигер, оҳангашро Ӯ. Алтаев навиштааст. Дар суруд бандҳо ва такрорбанд ҳаст.",
