"Ғарыш тақырыбындағы шығармаларды, олардың композиторларын атау және соната ұғымын түсіндіру.": "Асарҳои ба мавзӯи кайҳон бахшидашуда ва композиторони онҳоро номбар кардан ва мафҳуми сонатаро фаҳмонда додан.",
"Ғарыш және музыка": "Кайҳон ва мусиқӣ",
"Адамдар ғарышты сұлулық пен үйлесімділіктің, бірлік пен ынтымақтың мекені деп санаған. Ғарышқа жол ашылмай тұрған ғасырларда да ұлы композиторлар ғарыш әсемдігін музыка арқылы берген.": "Мардум кайҳонро макони зебоӣ ва мувофиқат, ягонагӣ ва ҳамдилӣ мешумориданд. Ҳатто дар асрҳое, ки роҳ ба кайҳон боз нашуда буд, композиторони бузург зебоии кайҳонро тавассути мусиқӣ тасвир мекарданд.",
"Ұлы композиторлар": "Композиторони бузург",
"А. Вивальди — итальяндық, Л. Бетховен — неміс композиторы. Олармен бірге В.А. Моцарт та ғарыш тақырыбын музыкасында көрсеткен. Вивальди есімімен Меркурий ғаламшарындағы бір кратер аталады.": "А. Вивалди — композитори итолиёвӣ, Л. Бетховен — композитори олмонӣ. Бо онҳо В.А. Моцарт низ мавзӯи кайҳонро дар мусиқиаш нишон додааст. Ба номи Вивалди як кратер дар сайёраи Меркурий номгузорӣ шудааст.",
"Ғарыштық атаулар": "Номҳои кайҳонӣ",
"Композиторлар өз шығармаларына ғаламшар мен ай аттарын қойған. Мысалы, Моцарттың «Юпитер» симфониясы және Бетховеннің «Ай нұры» сонатасы.": "Композиторон ба асарҳои худ номи сайёраҳо ва моҳро гузоштаанд. Масалан, симфонияи «Юпитер»-и Моцарт ва сонатаи «Нури Моҳ»-и Бетховен.",
"Соната дегеніміз не?": "Соната чист?",
"Соната — бірнеше қарама-қарсы бөліктен тұратын аспаптық шығарма. «Ай нұры» сонатасы фортепиано аспабына арналған. Оны зейін қойып, тыныш тыңдайды.": "Соната — асари асбобӣ, ки аз якчанд қисми муқобил иборат аст. Сонатаи «Нури Моҳ» барои асбоби фортепиано навишта шудааст. Онро бо диққат ва оромона гӯш мекунанд.",
"Қазіргі заман музыкасы": "Мусиқии замони муосир",
"Ғарыш тақырыбы бүгінгі музыкада да бар: француз композиторы Д. Маруани «Спейс» рок тобын басқарған, ал Ч. Айвз ғарыштық музыкасымен белгілі. Француз композиторы Жан Мишель Жарр заманауи музыканың дамуына үлес қосқан.": "Мавзӯи кайҳон дар мусиқии имрӯза низ ҳаст: композитори фаронсавӣ Д. Маруани гурӯҳи рокии «Спейс»-ро роҳбарӣ кардааст, Ч. Айвз бошад бо мусиқии кайҳонии худ маъруф аст. Композитори фаронсавӣ Жан Мишел Жарр ба рушди мусиқии муосир саҳм гузоштааст.",
"Бұрынғы шебер ме, бүгінгі музыка ма?": "Устоди гузашта ё мусиқии имрӯза?",
