"«Қыз Жібек» жырының, «Гәкку» мен «Ақ сиса» әндерінің авторларын, нұсқаларын және ерекшеліктерін ажырата білу.": "Муаллифон, нусхаҳо ва хусусиятҳои достони «Қиз Жибек» ва сурудҳои «Гакку» ва «Ақ сиса»-ро фарқ карда тавонистан.",
"Болашақ арманнан басталады": "Оянда аз орзу оғоз мешавад",
"Әрбір өнер адамы өз туындылары болашақта орындалса деп армандайды. Ескі әндер мен жырлар бізге жетіп, әлі де орындалып келеді.": "Ҳар як соҳиби санъат орзу мекунад, ки асарҳояш дар оянда иҷро шаванд. Сурудҳо ва жырҳои қадим ба мо расидаанд ва ҳанӯз ҳам иҷро мешаванд.",
