"«Қыз Жібек» жырына көркем фильм түсірілді, сахналық және опералық қойылымдар қойылды. Операны Е. Брусиловский жазған.": "Бар асоси жыри «Қиз Жибек» филми бадеӣ ба навор гирифта шуд, намоишҳои саҳнавӣ ва операвӣ гузошта шуданд. Операро Е. Брусиловский навиштааст.",
"«Гәкку» әні": "Суруди «Гакку»",
"Әнін де, өлеңін де Үкілі Ыбырай атанған Ыбырай Сандыбайұлы жазған. Брусиловский операда Жібек бейнесін ашу үшін бұл әнді лейттема ретінде қолданған.": "Ҳам оҳанг ва ҳам шеърашро Ибройи Сандибайулы, ки бо номи Укили Иброй маъруф аст, навиштааст. Брусиловский барои ошкор кардани симои Жибек дар опера ин сурудро ҳамчун лейттема истифода кардааст.",
"Жаяу Мұса және «Ақ сиса»": "Жаяу Мӯсо ва «Ақ сиса»",
