"Бір күйдің дәстүрлі және заманауи орындалуын салыстыра білу, домбыраның уақыт өте өзгергенін түсіндіру.": "Муқоиса карда тавонистани иҷрои анъанавӣ ва муосири як кюй, фаҳмонда додани тағйир ёфтани домбыра бо мурури замон.",
