"«Жұмыр-Қылыш» — ақын Махамбет Өтемісұлының күйі. Бұл күйдің әуені 2/4 өлшемде жазылған.": "«Жумир-Қилиш» — кюи шоир Маҳамбет Ӯтемисулы. Оҳанги ин кюй дар андозаи 2/4 навишта шудааст.",
