"Электронды музыкалық аспаптар мен сахналық шоуды танып, «Мен қазақпын» және «Асыл арман» әндері туралы айта білу": "Шинохтани асбобҳои мусиқии электронӣ ва шоуи саҳнавӣ ва тавонистани нақл кардан дар бораи сурудҳои «Ман қазақам» ва «Асыл арман»",
