"Ол — француз электронды музыканты. Өз шоуларында қызықты заманауи құралдарды қолданады.": "Ӯ — навозандаи электронии фаронсавӣ. Дар шоуҳояш асбобҳои ҷолиби муосирро истифода мебарад.",
"Лазерлік арфа өзі дыбыс шығармайды. Ол ноталарды басқа синтезаторларға бағыттайды.": "Арғунуни лазерӣ худаш садо намебарорад. Он нотаҳоро ба синтезаторҳои дигар равона мекунад.",
"Шоу және рэп": "Шоу ва рэп",
"Шоу — көңіл көтеретін бағдарламаға құрылған қойылым, іс-шара. Рэп — речитативтік (өлеңдетіп оқу) ырғақтық музыка.": "Шоу — намоиш ва чорабинии ба барномаи фароғатӣ асосёфта. Рэп — мусиқии пурнавои ритмӣ бо речитатив (хондани шеърӣ).",
