"«Асыл арман» әні тек ересектердің хорына арналған.": "Суруди «Асыл арман» танҳо барои хори калонсолон пешбинӣ шудааст.",
"«Мен қазақпын» әні туралы тапсырмада отансүйгіштік пен батылдық сияқты құндылықтарды атау ұсынылады.": "Дар супориш дар бораи суруди «Ман қазақам» пешниҳод мешавад, ки арзишҳо ба монанди ватандӯстӣ ва далерӣ номбар карда шаванд.",
"Иә, ол француз электронды музыканты.": "Бале, ӯ навозандаи электронии фаронсавӣ аст.",
"Ол өзі дыбыс шығармайды, ноталарды синтезаторларға бағыттайды.": "Ӯ худаш садо намебарорад, нотаҳоро ба синтезаторҳо равона мекунад.",
"Дұрыс, шоу осындай қойылым, іс-шара.": "Дуруст, шоу чунин намоиш ва чорабинӣ аст.",
"Оны испан өнер тапқыштары ойлап тапқан.": "Онро ихтироъкорони испанӣ ихтироъ кардаанд.",
"Иә, бетіне дыбыс генераторлары орналасқан.": "Бале, дар сатҳаш генераторҳои садо ҷойгиранд.",
"Оны бір немесе бірнеше адам ойнай алады.": "Онро як нафар ё якчанд нафар навохта метавонанд.",
"Ол жеке орындаушылар мен балалар хорына арналған.": "Он барои иҷрогарони алоҳида ва хори кӯдакон пешбинӣ шудааст.",
"Иә, әндегі құндылықтарды атау керек, мысалы отансүйгіштік, батылдық.": "Бале, арзишҳои суруд бояд номбар шаванд, масалан ватандӯстӣ, далерӣ.",
"Дұрыс. Иә, ол француз электронды музыканты.": "Дуруст. Бале, ӯ навозандаи электронии фаронсавӣ аст.",
"Бұрыс. Шоу Марокконың Сахара шөлінде өтті.": "Нодуруст. Шоу дар биёбони Сахараи Марокаш баргузор шуд.",
"Бұрыс. Ол өзі дыбыс шығармайды, ноталарды синтезаторларға бағыттайды.": "Нодуруст. Ӯ худаш садо намебарорад, нотаҳоро ба синтезаторҳо равона мекунад.",
"Дұрыс. Дұрыс, шоу осындай қойылым, іс-шара.": "Дуруст. Дуруст, шоу чунин намоиш ва чорабинӣ аст.",
"Дұрыс. Рэп — речитативтік ырғақтық музыка.": "Дуруст. Рэп — мусиқии пурнавои речитативӣ.",
"Бұрыс. Оны испан өнер тапқыштары ойлап тапқан.": "Нодуруст. Онро ихтироъкорони испанӣ ихтироъ кардаанд.",
"Дұрыс. Иә, бетіне дыбыс генераторлары орналасқан.": "Дуруст. Бале, дар сатҳаш генераторҳои садо ҷойгиранд.",
"Дұрыс. Оны бір немесе бірнеше адам ойнай алады.": "Дуруст. Онро як нафар ё якчанд нафар навохта метавонанд.",
"Бұрыс. Ол жеке орындаушылар мен балалар хорына арналған.": "Нодуруст. Он барои иҷрогарони алоҳида ва хори кӯдакон пешбинӣ шудааст.",
"Дұрыс. Иә, әндегі құндылықтарды атау керек, мысалы отансүйгіштік, батылдық.": "Дуруст. Бале, арзишҳои суруд бояд номбар шаванд, масалан ватандӯстӣ, далерӣ.",
"Табыңыз: Жан Мишель Жарр шоуы": "Ёбед: Шоуи Жан Мишель Жарр",
"Табыңыз: Реактейбл": "Ёбед: Реактейбл",
