"Табыңыз: Рэп": "Ёбед: Рэп",
"Табыңыз: Электронды аспап": "Ёбед: Асбоби электронӣ",
"34-сабақ. Қазақстан болашағы және музыка": "Дарс 34. Ояндаи Қазоқистон ва мусиқӣ",
"Қазақстан болашағы және музыка": "Ояндаи Қазоқистон ва мусиқӣ",
"Түсіндіру: дәстүрлі музыкалық өнер мен заманауи музыка болашақта қатар жүреді, ал болашаққа деген сенім өз құндылықтарымызды құрметтеумен байланысты.": "Шарҳ: санъати мусиқии анъанавӣ ва мусиқии муосир дар оянда паҳлӯ ба паҳлӯ мераванд, эътимод ба оянда бошад, ба эҳтироми арзишҳои худамон вобаста аст.",
"Бұл әннің композиторы — С. Еркімбеков. Әнде балалар қандай болашақ туралы армандайтыны айтылады.": "Оҳангсози ин суруд — С. Еркимбеков. Дар суруд гуфта мешавад, ки кӯдакон дар бораи чӣ гуна оянда орзу мекунанд.",
"Болашаққа сенім": "Эътимод ба оянда",
"Қазақстан бүгінгі күні нық сеніммен болашаққа алға басты. Мұндай сенімділік халықтың өз құндылықтарын құрметтеп, сақтап қалуымен тығыз байланысты.": "Қазоқистон имрӯз бо эътимоди мустаҳкам ба пеш қадам мегузорад. Чунин эътимод ба эҳтиром ва ҳифзи арзишҳои худи мардум зич алоқаманд аст.",
"Халықтың құндылықтары": "Арзишҳои мардум",
"Халықтың құндылықтарына оның тілі, дәстүрі, мәдениеті және өнері жатады. Оларды құрметтеп, сақтау — болашақтың негізі.": "Ба арзишҳои мардум забон, анъана, фарҳанг ва санъати он дохил мешавад. Эҳтиром ва ҳифзи онҳо — асоси оянда аст.",
"Дәстүр мен жаңашылдық": "Анъана ва навоварӣ",
"Дәстүрлі музыкалық өнер мен заманауи музыка өзара үйлесімділікте болашақта қатар жүреді. Олар бір-бірін жоққа шығармайды.": "Санъати мусиқии анъанавӣ ва мусиқии муосир дар ҳамоҳангӣ бо ҳам дар оянда паҳлӯ ба паҳлӯ мераванд. Онҳо якдигарро инкор намекунанд.",
"Әнді қалай орындайды": "Суруд чӣ тавр иҷро мешавад",
"«Асыл арман» әнінде жеке дауыс, хор және тақпақ түрінде айтылатын тұстар бар. Әнді халық аспаптары немесе оркестр сүйемелдеуі мүмкін.": "Дар суруди «Асыл арман» қисмҳое ҳастанд, ки бо овози алоҳида, хор ва шеърхонӣ хонда мешаванд. Суруд метавонад бо асбобҳои мардумӣ ё бо оркестр ҳамроҳӣ шавад.",
"Музыкалық стильдер, аспаптар және оркестрлер": "Услубҳои мусиқӣ, асбобҳо ва оркестрҳо",
"Әр карточканы өз тобына қой. Барсик көмектеседі!": "Ҳар кортро ба гурӯҳи худаш гузор. Барсик кӯмак мекунад!",
