"Лазерлік арфа түрлі түсті жарық шығарады.": "Арғунуни лазерӣ рӯшноии рангоранг мебарорад.",
"Реактейбл — үрлемелі аспап.": "Реактейбл — асбоби пуфакӣ.",
"Болашаққа деген сенім халықтың құндылықтарын құрметтеумен байланысты.": "Эътимод ба оянда ба эҳтироми арзишҳои мардум вобаста аст.",
"Болашақта тек заманауи музыка қалады, дәстүрлі өнер қажет емес.": "Дар оянда танҳо мусиқии муосир мемонад, санъати анъанавӣ лозим нест.",
"«Асыл арман» әні тек аспаптармен ойналады, онда дауыс жоқ.": "Суруди «Асыл арман» танҳо бо асбобҳо навохта мешавад, дар он овоз нест.",
